def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    values = sorted(set(a))
    rank = {value: i + 1 for i, value in enumerate(values)}
    bit = [0] * (len(values) + 1)

    def add(index: int, delta: int) -> None:
        while index < len(bit):
            bit[index] += delta
            index += index & -index

    def prefix_sum(index: int) -> int:
        total = 0
        while index:
            total += bit[index]
            index -= index & -index
        return total

    result = []
    window_size = 0

    for i, height in enumerate(a):
        r = rank[height]
        result.append(window_size - prefix_sum(r))

        add(r, 1)
        window_size += 1

        if window_size > k:
            old_rank = rank[a[i - k]]
            add(old_rank, -1)
            window_size -= 1

    return result
